$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$root='C:\JudasValidation';$base='http://192.168.122.1:8872'
function Upload($p,$n){Invoke-WebRequest -UseBasicParsing "$base/$n" -Method Post -InFile $p|Out-Null}
$m=$null
try{
 $m=(Invoke-WebRequest -UseBasicParsing "$base/m78-native-first-boundary-closure.json").Content|ConvertFrom-Json;$scratch=$m.scratch;$out=$m.output
 if(Test-Path $scratch){throw 'Preserve existing closure scratch'};if((Get-PSDrive C).Free -lt 40MB){throw 'Insufficient owned closure headroom'};New-Item -ItemType Directory "$scratch\objects",$out|Out-Null
 if((Get-FileHash $m.library.path).Hash.ToLower() -ne $m.library.sha256){throw 'Frozen final archive changed'};if((Get-FileHash $m.save.path).Hash.ToLower() -ne $m.save.sha256){throw 'Exact a106 input changed'}
 $zip="$scratch\source.zip";Invoke-WebRequest -UseBasicParsing "$base/$($m.archiveName)" -OutFile $zip;if((Get-FileHash $zip).Hash.ToLower() -ne $m.archiveSHA256){throw 'Source bundle SHA mismatch'};Expand-Archive $zip "$scratch\source"
 foreach($f in $m.files){$p=Join-Path "$scratch\source" $f.path;if((Get-Item $p).Length -ne $f.bytes -or (Get-FileHash $p).Hash.ToLower() -ne $f.sha256){throw ('Exact input identity mismatch '+$f.path)}}
 Import-Module "$root\VS2022\Common7\Tools\Microsoft.VisualStudio.DevShell.dll";Enter-VsDevShell -VsInstallPath "$root\VS2022" -SkipAutomaticLocation -DevCmdArguments '-arch=x64 -host_arch=x64';Set-Location "$root\Build";$compiles=@();$ErrorActionPreference='Continue'
 foreach($unit in @(@{name='JointSolver';path='src/JointSolver.cpp';flags=$m.engineFlags},@{name='PhysicalBalance';path='src/PhysicalBalance.cpp';flags=$m.engineFlags},@{name='BalanceLabBoundaryObserver';path='probes/BalanceLabBoundaryObserver.cpp';flags=$m.caseFlags})){
  $source=Join-Path "$scratch\source" $unit.path;$obj="$scratch\objects\$($unit.name).obj";$flags=[string]$unit.flags
  $flags=[regex]::Replace($flags,'/Fo"[^"]*"',('/Fo"'+$obj+'"'),'IgnoreCase');$flags=[regex]::Replace($flags,'/Fd"[^"]*"',('/Fd"'+$scratch+'\objects\compile.pdb"'),'IgnoreCase');$flags=[regex]::Replace($flags,'\s+C:\\JUDASVALIDATION\\SOURCE\\[^\r\n]*\.CPP\s*$','','IgnoreCase');$flags='/I"'+$scratch+'\source\src" /I"'+$root+'\Source\third_party" '+$flags+' "'+$source+'"'
  $rsp="$scratch\objects\$($unit.name)-compile.rsp";[IO.File]::WriteAllText($rsp,$flags,[Text.UTF8Encoding]::new($false));$log="$out\m78-first-closure-$($unit.name)-compile.log";[IO.File]::WriteAllText($log,'');& cl.exe "@$rsp" 2>&1|Tee-Object -FilePath $log;$code=$LASTEXITCODE;Upload $log ([IO.Path]::GetFileName($log));if($code -ne 0){throw ('Copied diagnostic compile failed '+$unit.name)};$compiles+=@{source=$source;sha256=(Get-FileHash $source).Hash.ToLower();object=$obj;objectSHA256=(Get-FileHash $obj).Hash.ToLower();response=$flags}
 }
 $env:GALLIUM_DRIVER='llvmpipe';$env:JUDAS_ENGINE_ROOT="$root\Source";$env:TEMP="$out\temp";$env:TMP=$env:TEMP;New-Item -ItemType Directory $env:TEMP -Force|Out-Null
 foreach($n in @('JUDAS_DIAGNOSTIC_RESTORE_DRIVES','JUDAS_BOUNDARY_DISCARD_FIRST_JOINT_SEEDS','JUDAS_BOUNDARY_ORACLE_FIRST_SOLVE','JUDAS_BOUNDARY_ORACLE_ALL_SOLVES','JUDAS_DIAGNOSTIC_CONTINUE_WRITE')){[Environment]::SetEnvironmentVariable($n,$null,'Process')};$env:JUDAS_BOUNDARY_REPLAY_CAPTURED_NATIVE='1';$env:JUDAS_BOUNDARY_STEPS='1';$runs=@()
 foreach($variant in @('commands-seeds','commands-seeds-normal-prepare')){
  $name="m78-native-first-closure-$variant";$exe="$root\Build\Release\$name.exe";if(Test-Path $exe){throw 'Preserve preceding observer executable'}
  $map="$out\$name.map";$link=[string]$m.linkFlags;$link=[regex]::Replace($link,'/OUT:"[^"]*"',('/OUT:"'+$exe+'"'),'IgnoreCase');$link=[regex]::Replace($link,'RELEASE\\JUDAS_ENGINE\.LIB',('"'+$m.library.path+'"'),'IgnoreCase');$link=[regex]::Replace($link,'/PDB:"[^"]*"',('/PDB:"'+$scratch+'\objects\'+$variant+'.pdb"'),'IgnoreCase');$link=[regex]::Replace($link,'/IMPLIB:"[^"]*"',('/IMPLIB:"'+$scratch+'\objects\'+$variant+'.lib"'),'IgnoreCase');$prefix='"'+$scratch+'\objects\BalanceLabBoundaryObserver.obj" "'+$scratch+'\objects\JointSolver.obj" ';if($variant -eq 'commands-seeds-normal-prepare'){$prefix+='"'+$scratch+'\objects\PhysicalBalance.obj" '};$link=$prefix+$link+' /VERBOSE:LIB /MAP:"'+$map+'"';$rsp="$scratch\objects\$variant-link.rsp";[IO.File]::WriteAllText($rsp,$link,[Text.UTF8Encoding]::new($false));$log="$out\$name-link.log";[IO.File]::WriteAllText($log,'');& link.exe "@$rsp" 2>&1|Tee-Object -FilePath $log;$code=$LASTEXITCODE;Upload $log ([IO.Path]::GetFileName($log));Upload $map ([IO.Path]::GetFileName($map));if($code -ne 0){throw ('Diagnostic link failed '+$variant)}
  $bad=@(Get-Content $log|Where-Object {$_ -match 'Loaded.*judas_engine\.lib\([^)]*JointSolver\.obj\)' -or ($variant -eq 'commands-seeds-normal-prepare' -and $_ -match 'Loaded.*judas_engine\.lib\([^)]*PhysicalBalance\.obj\)')});if($bad.Count){throw ('Original replaced archive member extracted '+($bad -join ';'))}
  $dest="$out\$variant";New-Item -ItemType Directory "$dest\slots"|Out-Null;Copy-Item $m.project "$dest\project" -Recurse;Copy-Item $m.save.path "$dest\slots\m77.save";if((Get-FileHash "$dest\slots\m77.save").Hash.ToLower() -ne $m.save.sha256){throw 'Fresh input save differs'}
  $watch=[Diagnostics.Stopwatch]::StartNew();$p=Start-Process -FilePath $exe -ArgumentList @($dest,'cold-read') -WorkingDirectory "$root\Source" -PassThru -RedirectStandardOutput "$out\$name.stdout.log" -RedirectStandardError "$out\$name.stderr.log";[void]$p.Handle;if(!$p.WaitForExit(600000)){Stop-Process -Id $p.Id -Force;$exit='owned diagnostic timeout'}else{$p.Refresh();$exit=$p.ExitCode};$watch.Stop();$files=@()
  foreach($f in Get-ChildItem $dest -File|Where-Object {$_.Extension -in '.json','.jsonl'}){$rn="$name-$($f.Name)";Upload $f.FullName $rn;$files+=@{path=$f.FullName;reportName=$rn;sha256=(Get-FileHash $f.FullName).Hash.ToLower();bytes=$f.Length}}
  $row=@{scope=$m.scope;variant=$variant;exitCode=$exit;seconds=$watch.Elapsed.TotalSeconds;executable=$exe;executableSHA256=(Get-FileHash $exe).Hash.ToLower();library=$m.library;compiles=$compiles;linkerResponse=$link;linkMapSHA256=(Get-FileHash $map).Hash.ToLower();linkLogSHA256=(Get-FileHash $log).Hash.ToLower();inputSaveSHA256=(Get-FileHash "$dest\slots\m77.save").Hash.ToLower();sourceBundleSHA256=$m.sourceBundleSHA256;arguments=@($dest,'cold-read');files=$files;freeBytes=(Get-PSDrive C).Free};$runs+=$row;$rp="$out\$name.json";$row|ConvertTo-Json -Depth 8|Set-Content $rp -Encoding UTF8;Upload $rp "$name.json";Upload "$out\$name.stdout.log" "$name.stdout.log";Upload "$out\$name.stderr.log" "$name.stderr.log"
 }
 $rp="$out\m78-native-first-closure-pair.json";@{runs=$runs;freeBytes=(Get-PSDrive C).Free}|ConvertTo-Json -Depth 9|Set-Content $rp -Encoding UTF8;Upload $rp ([IO.Path]::GetFileName($rp))
}catch{$out=$(if($m){$m.output}else{'C:\JudasValidation\M78NativeFunctionalResults'});New-Item -ItemType Directory $out -Force|Out-Null;$name='m78-native-first-closure-error.txt';[string]$_.Exception.Message|Set-Content "$out\$name";Upload "$out\$name" $name;exit 1}
